#[cfg(test)]
mod tests {
    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::application::{RetryFence, may_retry};
    use rigorix_engine::effect_commitment::domain::{
        EffectIntent, EffectRecord, ObservedOutcome, ResolverIdentity, ResolverKind,
    };
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            1,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        )
    }

    #[test]
    fn test_retryfence_is_defined() {
        fn assert_object_safe(_: Option<Box<dyn RetryFence>>) {}
        assert_object_safe(None);
    }

    #[test]
    fn test_retryfence_interacts_with_effectstate() {
        fn assert_send_sync<T: Send + Sync + ?Sized>() {}
        assert_send_sync::<dyn RetryFence>();

        // F2: a dispatched (not yet settled) effect may still be settled, but an
        // ambiguous one may not be re-dispatched.
        let dispatched = EffectRecord::begin(intent());
        assert!(may_retry(&dispatched));

        let ambiguous = dispatched
            .clone()
            .mark_ambiguous("response lost", Utc::now())
            .unwrap();
        assert!(!may_retry(&ambiguous));

        // A new attempt after resolution is permitted.
        let resolved = ambiguous
            .resolve(
                ObservedOutcome::not_committed("receipt-1", "readback-1", Utc::now(), "stripe"),
                ResolverIdentity::new("stripe", ResolverKind::Provider, "readback-1"),
                Utc::now(),
            )
            .unwrap();
        assert!(may_retry(&resolved));
    }
}
